// Actions

function sortSolutionsAscending() {
  Replace( Get("#solutions"), Array.from(Get("#solutions").children).sort( (a,b) => a.dataset.id > b.dataset.id ) )
}


function sortSolutionsDescending() {
  Replace( Get("#solutions"), Array.from(Get("#solutions").children).sort( (a,b) => a.dataset.id < b.dataset.id ) )
}


function sortSolutionsCustom() {
	const ingredientMap = new Map()
	const solutions = [...GetAll(".solution")].map( solution => {
		const result = solution.dataset.id
		const ingredients = [...GetAll(".element.ingredient", solution)].map( ingredient => {
			const name = ingredient.textContent.toLowerCase()
			const found = ingredient.classList.contains("have")	
			
			if ( ingredientMap.has(name) ) {
				ingredientMap.get(name).count++
			} else {
				ingredientMap.set( name, { count: 1, found } )
			}
			
			return {
				name,
				found
			}
		} )
		
		const foundIngredientFraction = ingredients.reduce( (acc, cur) => acc + +(cur.found), 0 ) / ingredients.length
		
		return {
			solution,
			result,
			ingredients,
			foundIngredientFraction
		}
	} )
	
	sortSolutionsAscending()
	//console.log( 
		//solutions.map( solution => solution.ingredients.map( ing => ingredientMap.get(ing.name).count ) )
	//)
	solutions.sort( (a, b) => Math.max( ...a.ingredients.map( ing => ingredientMap.get(ing.name).count ) ) < Math.max( ...b.ingredients.map( ing => ingredientMap.get(ing.name).count ) ) )
		
	solutions.sort( (a, b) => a.foundIngredientFraction < b.foundIngredientFraction )
	
	//return { solutions, ingredientMap }
	
  Replace(
		Get("#solutions"),
		solutions.map( solution => solution.solution )
	)
}


function reverseSolutions() {
  Replace( Get("#solutions"), Array.from(Get("#solutions").children).reverse() )
}


function clearAllSolutions() {
  Replace( Get("#solutions") )
}


function toggleAddAll() {
  window.enableAddAll = !window.enableAddAll
  if ( window.enableAddAll ) {
    Get("#searchbtn").textContent = "Add All"
  }
  else {
    Get("#searchbtn").textContent = "Add"
  }
}


function loadAllRecipes() {
  if ( !document.querySelector("script[src=\"data_create_remaining_recipes.js\"]") ) {
    Append( document.head, Create( "script", { attr:{ src:"data/data_create_remaining_recipes.js", type:"text/javascript" } } ) )
  }
}


function removeFoundResults() {
	document.querySelectorAll(".element.result.have").forEach( result => result.parentElement.remove() )
}


function removeFullyFoundResults() {
	document.querySelectorAll(".solution").forEach( solution => {
		if ( [...solution.querySelectorAll(".element")].every( element => element.matches(".have") ) )
			solution.remove()
	} )
}


function removeFullyExistingResults() {
	document.querySelectorAll(".solution").forEach( solution => {
		if ( [...solution.querySelectorAll(".element")].every( element => element.matches(".have") || element.matches(":not(.norecipe)") ) )
			solution.remove()
	} )
}


function removeExistingResults() {
	document.querySelectorAll(".element.result:not(.norecipe)").forEach( result => result.parentElement.remove() )
}


function removeNonExistingResults() {
	document.querySelectorAll(".element.result.norecipe").forEach( result => result.parentElement.remove() )
}


