function addCombination(combination, ingredientList) {
  //console.log(combination, ingredientList)
  const packed = []
  let lastId = combination[0]
  let count = 1

  for (let i = 1; i < combination.length; i++) {
    if (combination[i] === lastId) {
      count++
    } else {
      packed.push({ id: lastId, count })
      lastId = combination[i]
      count = 1
    }
  }
  if (combination.length)
    packed.push({ id: lastId, count })
  packed.forEach( (item, i) => {
    if (i > 0) {
      ingredientList.appendChild(document.createTextNode(' + '))
    }

    const element = createElementSpan(item.id)
    const className = elementsByName.size ? ( elementsByName.get( getName(item.id)?.toLowerCase() ) ? "have" : "missing" ) : null
    if ( className ) {
      element.classList.add(className)
    }
    
    element.classList.add("ingredient")
    
    if ( data.info[item.id]?.[0] === "5" ) {
      element.classList.add("boosted")
    }
    
    ingredientList.appendChild(element)

    if (item.count > 1) {
      ingredientList.appendChild(document.createTextNode(" ×" + item.count))
    }
  } )
}


function addSolutions(resultId, afterNode, customCreates) {
  const id = typeof resultId === "number" ? formatBack(getName(resultId)) : resultId

  const existingSolution = document.querySelector(`[data-id="${id}"]`)
  if (existingSolution) {
    existingSolution.remove()
    
    if ( afterNode ) {
      afterNode.after(existingSolution)
    } else {
      Get("#solutions").prepend(existingSolution)
    }
    
    flashDiv(existingSolution)
    return
  }

  const solution = document.createElement('div')
  solution.classList.add('solution')
  solution.dataset.id = id

  const creates = customCreates ?? ( typeof resultId === "number" ? window.data.create[resultId] : undefined )

  const close = document.createElement('span')
  close.classList.add('close')
  close.addEventListener('click', function () {
    solution.remove()
  })
  solution.appendChild(close)

  const recipeResult = createElementSpan(resultId, false)
  const elementListLoaded = !!elementsByName.size
  const className = elementListLoaded ? ( elementsByName.get( getName(resultId)?.toLowerCase() ) ? "have" : "missing" ) : null
  if ( className )
    recipeResult.classList.add(className)
  recipeResult.classList.add("result")
  
  if ( typeof resultId === "number" && data.info[resultId][0] === "5" ) {
    recipeResult.classList.add("boosted")
  }
  
  solution.appendChild( recipeResult )
  
	if (creates?.length)
  	solution.appendChild( document.createTextNode(' = ') )
  
  const ingredientContainer = Create("span")
  ingredientContainer.classList.add("ingredientcontainer")
  solution.appendChild( ingredientContainer )
  
  let ingredientList = Create("span")
  ingredientList.classList.add("ingredientlist")
  ingredientContainer.appendChild( ingredientList )

  for (let i = 0; i < creates?.length; i++) {
    if (i > 0) {
      ingredientList = Create("span")
      ingredientList.classList.add("ingredientlist")
      ingredientList.appendChild( document.createElement('br')  )
      ingredientList.appendChild( document.createTextNode("or ") )
      ingredientContainer.appendChild( ingredientList )
    }
    addCombination(creates[i], ingredientList)
  }

  solution.appendChild( document.createElement('br') )

  if ( afterNode ) {
    afterNode.after(solution)
    //solution.scrollIntoView()
  }
  else
    document.querySelector("#solutions").prepend(solution)
}


function addSolutionsFrom2dText(text) {
	const solutions = text
	.trim()
	.toLowerCase()
	.split(/\r?\n/)
	.map( line => ( line.match( /^\s*[a-zA-Z0-9 '-]+(?: \+ [a-zA-Z0-9 '-]+){1,3} = [a-zA-Z0-9 '-]+\s*$/ ) ? line.split(/=|\+/).reverse() : line.split(/\t|=|\+|,|;/) )
		.map( elem => elem.replaceAll( /[^a-z0-9 \-']/g, "" ).trim() )
    .filter( elem => elem !== "" )
		.map( elem => elem === "twao" ? "two-word answers only" : elem )
		.map( elem => ~getId(elem) ? getId(elem) : elem )
	)
  .filter( solution => solution.length )
  
  if ( solutions.length ) {
    solutions.reverse().forEach( recipe => {
      const chosenRecipe = recipe.length === 1 ? null : [recipe.slice(1)]
      addSolutions( recipe[0], null, chosenRecipe )
    } )    
  }
  
  updateElementStatus()
}


